/* @lc app=leetcode id=2746 lang=kotlin */ class Solution { fun minimizeConcatenatedLength(words: Array<String>): Int = words.drop(1).fold(mapOf((words[0].first() to words[0].last()) to words[0].length)) { dp, w -> mutableMapOf<Pair<Char, Char>, Int>().apply { dp.forEach { (k, v) -> (v + w.length - (if (k.second == w.first()) 1 else 0)).let { c1 -> run { this[k.first to w.last()] = minOf(this[k.first to w.last()] ?: 2000000, c1) } }.run { v + w.length - (if (w.last() == k.first) 1 else 0) }.let { c2 -> run { this[w.first() to k.second] = minOf(this[w.first() to k.second] ?: 2000000, c2) } } } } }.values.minOrNull() ?: 0 }